import json
import requests
import chardet

API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if detected is None or detected.get('encoding') is None:
            raise ValueError("Unable to detect encoding for non-empty content")
        source_enc = detected['encoding']
    else:
        source_enc = from_encoding
    decoded_str = content.decode(source_enc)
    reencoded_bytes = decoded_str.encode(to_encoding)
    final_str = reencoded_bytes.decode(to_encoding)
    return json.loads(final_str)

