from collections import Counter

def task_func(json_str, top_n=10):
    data = json.loads(json_str)
    urls = []
    pattern = re.compile(r'https?://[^\s"\'<>]+')

    def extract_strings(obj):
        if isinstance(obj, str):
            urls.extend(pattern.findall(obj))
        elif isinstance(obj, dict):
            for v in obj.values():
                extract_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                extract_strings(item)

    extract_strings(data)
    counter = Counter(urls)
    if top_n > 0:
        return dict(counter.most_common(top_n))
    return dict(counter)

import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    def extract_strings(obj):
        if isinstance(obj, str):
            yield obj
        elif isinstance(obj, dict):
            for v in obj.values():
                yield from extract_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_strings(item)

    url_pattern = r'https?://[^\s"<>]+'
    data = json.loads(json_str)
    urls = []
    for s in extract_strings(data):
        urls.extend(re.findall(url_pattern, s))
    counter = Counter(urls)
    if top_n is not None and top_n > 0:
        counter = dict(counter.most_common(top_n))
    else:
        counter = dict(counter)
    return counter

