import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    all_text = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                    if 'text' in data:
                        all_text.append(data['text'])
                except (json.JSONDecodeError, KeyError):
                    continue
    combined = ' '.join(all_text)
    combined = combined.lower()
    import string
    combined = ''.join(ch for ch in combined if ch not in string.punctuation and (ch.isalnum() or ch.isspace()))
    words = combined.split()
    word_counts = Counter(words)
    return word_counts.most_common(word_count)

def task_func(json_dir_path, word_count):
