import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [process(item) for item in obj]
        elif obj is None:
            return REPLACE_NONE
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    data = json.loads(json_str)
    processed = process(data)

    def flatten(obj):
        items = []
        if isinstance(obj, dict):
            for v in obj.values():
                items.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                items.extend(flatten(item))
        else:
            items.append(obj)
        return items

    values = flatten(processed)
    value_counts = Counter(values)

    return {"data": processed, "value_counts": value_counts}

