from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r'[\w\.-]+@[\w\.-]+\.\w+')
    def clean(obj):
        if isinstance(obj, dict):
            cleaned = {}
            for k, v in obj.items():
                cv = clean(v)
                if cv is not None:
                    cleaned[k] = cv
            return cleaned if cleaned else None
        elif isinstance(obj, list):
            cleaned = [clean(item) for item in obj if clean(item) is not None]
            return cleaned if cleaned else None
        elif isinstance(obj, str):
            return REPLACE_NONE if email_pattern.fullmatch(obj) else obj
        else:
            return obj
    cleaned_data = clean(data)
    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from flatten(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from flatten(item)
        else:
            yield obj
    all_values = list(flatten(cleaned_data))
    value_counts = Counter(all_values)
    return {"data": cleaned_data, "value_counts": value_counts}

