        population = entry.get('population')
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if isinstance(population, float):
            population = int(math.floor(population))
        if population < 0:
            raise ValueError("Population cannot be negative")
        records.append({'Country': country, 'Population': population})
    df = pd.DataFrame(records, columns=['Country', 'Population'])
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except OSError:
        raise IOError("Cannot write file to specified directory")
    return os.path.abspath(file_path), df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    obj = json.loads(json_data)
    current = obj
    for key in key_path:
        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        else:
            raise KeyError(key)
    if isinstance(current, list):
        numeric = []
        for item in current:
            if isinstance(item, (int, float)):
                numeric.append(item)
            else:
                raise ValueError("Non-numeric data found in list")
        if len(numeric) == 0:
            raise ValueError("No numeric data found")
    elif isinstance(current, str):
        if current.strip() == '':
            raise ValueError("Data string is empty")
        try:
            parsed = json.loads(current)
            if isinstance(parsed, list):
                numeric = [x for x in parsed if isinstance(x, (int, float))]
                if len(numeric) == 0:
                    raise ValueError("No numeric data found in parsed list")
            else:
                raise ValueError("Data string does not represent a list")
        except (json.JSONDecodeError, ValueError):
            try:
                parts = current.split(',')
                numeric = [float(part.strip()) for part in parts if part.strip() != '']
                if len(numeric) == 0:
                    raise ValueError("No numeric data found after splitting")
            except ValueError:
                raise ValueError("Data string is corrupted")
    elif isinstance(current, (int, float)):
        numeric = [current]
    else:
        raise ValueError("No numeric data found")
    fig, ax = plt.subplots()
    sns.boxplot(data=numeric, ax=ax)
    return fig

