            raise ValueError("corrupted data string")
    elif isinstance(current, list):
        if not current:
            raise ValueError("no numeric data found")
        try:
            values = [float(x) for x in current]
        except (TypeError, ValueError):
            raise ValueError("corrupted data list")
    else:
        raise ValueError("unsupported data type")
    if not values:
        raise ValueError("no numeric data found")
    fig, ax = plt.subplots()
    ax.boxplot(values)
    ax.set_title("Boxplot of extracted data")
